package main

import "fmt"

// Logger is a small mixin we will embed.
type Logger struct {
	Prefix string
}

func (l Logger) Log(msg string) { // value-receiver method
	fmt.Printf("[%s] %s\n", l.Prefix, msg)
}

// Base holds shared fields and embeds Logger (an embedded field inside an embedded field).
type Base struct {
	ID int
	Logger // anonymous field: Logger's Prefix and Log are promoted
}

// User embeds Base. ID, Log, Prefix all promote up to User.
type User struct {
	Base        // anonymous field; the field name is literally "Base"
	Name string
}

func main() {
	u := User{
		Base: Base{ID: 7, Logger: Logger{Prefix: "USER"}},
		Name: "Ada",
	}

	// Promoted field: u.ID resolves to u.Base.ID.
	fmt.Println("ID:", u.ID)

	// Promoted method (two levels deep): u.Log -> u.Base.Logger.Log.
	u.Log("created")

	// Promoted field from the deeper embed.
	fmt.Println("Prefix:", u.Prefix)

	// Access the embedded value explicitly by its type name.
	u.Base.ID = 99
	fmt.Println("via u.Base.ID:", u.ID)
	u.Base.Logger.Log("explicit path")
}

package main

import (
	"bytes"
	"fmt"
	"io"
)

// Interface embedding: ReadWriteCloser is the union of three method sets.
// (This is exactly how the standard library defines io.ReadWriteCloser.)
type ReadWriteCloser interface {
	io.Reader // embedded interface
	io.Writer // embedded interface
	io.Closer // embedded interface
}

// upperReader embeds io.ReadCloser. By storing an implementation in the
// anonymous interface field, upperReader already satisfies io.ReadCloser:
// Close is delegated automatically, and we override only Read.
type upperReader struct {
	io.ReadCloser // embedded INTERFACE field; supplies Read and Close
}

// Override Read: read from the embedded impl, then uppercase ASCII letters.
func (u upperReader) Read(p []byte) (int, error) {
	n, err := u.ReadCloser.Read(p) // delegate to the wrapped reader
	for i := 0; i < n; i++ {
		if p[i] >= 'a' && p[i] <= 'z' {
			p[i] -= 32 // to uppercase
		}
	}
	return n, err
}

func main() {
	// io.NopCloser gives us a ReadCloser whose Close is a no-op.
	base := io.NopCloser(bytes.NewBufferString("hello go"))
	var rc io.ReadCloser = upperReader{ReadCloser: base}

	out, _ := io.ReadAll(rc) // uses our overridden Read
	fmt.Printf("%s\n", out)

	if err := rc.Close(); err == nil { // delegated to embedded Close
		fmt.Println("closed via promoted Close")
	}
}

package main

import "fmt"

type Animal struct {
	Name string
}

// Sound is the "base" behavior.
func (a Animal) Sound() string { return "..." }

// Describe calls Sound INTERNALLY. In Java this would dispatch to an override.
func (a Animal) Describe() string {
	return a.Name + " says " + a.Sound() // calls Animal.Sound, NOT Dog.Sound
}

type Dog struct {
	Animal // embedded
}

// Dog shadows Sound. This wins for direct calls dog.Sound().
func (d Dog) Sound() string { return "Woof" }

func main() {
	d := Dog{Animal{Name: "Rex"}}

	// Direct call uses the shadowing (depth-0) method: Dog.Sound.
	fmt.Println("d.Sound():", d.Sound())

	// Promoted Describe runs Animal.Describe, whose internal a.Sound()
	// statically dispatches to Animal.Sound — NOT Dog.Sound. No virtual dispatch.
	fmt.Println("d.Describe():", d.Describe())

	// To get the embedded version explicitly, qualify by type name.
	fmt.Println("d.Animal.Sound():", d.Animal.Sound())

	// The Go way to get "polymorphism": call through an interface you implement.
	fmt.Println("explicit override result:", d.Name+" says "+d.Sound())
}
